create table if not exists public.care_registration_signups (user_id uuid primary key references auth.users(id) on delete cascade,email text not null,created_at timestamptz not null default now(),confirmed_at timestamptz); alter table public.care_registration_signups enable row level security; revoke all on public.care_registration_signups from anon; grant select on public.care_registration_signups to authenticated; drop policy if exists "platform admin reads pending signups" on public.care_registration_signups; create policy "platform admin reads pending signups" on public.care_registration_signups for select to authenticated using (public.is_nextvita_platform_admin()); create or replace function public.sync_care_registration_signup() returns trigger language plpgsql security definer set search_path=public as $$ begin if tg_op='INSERT' then insert into public.care_registration_signups(user_id,email,confirmed_at) values(new.id,coalesce(new.email,''),new.email_confirmed_at) on conflict(user_id) do update set email=excluded.email,confirmed_at=excluded.confirmed_at; else update public.care_registration_signups set email=coalesce(new.email,''),confirmed_at=new.email_confirmed_at where user_id=new.id; end if; return new; end; $$; revoke all on function public.sync_care_registration_signup() from public,anon,authenticated; drop trigger if exists care_registration_signup_created on auth.users; create trigger care_registration_signup_created after insert on auth.users for each row execute function public.sync_care_registration_signup(); drop trigger if exists care_registration_signup_updated on auth.users; create trigger care_registration_signup_updated after update of email,email_confirmed_at on auth.users for each row execute function public.sync_care_registration_signup(); insert into public.care_registration_signups(user_id,email,confirmed_at) select id,coalesce(email,''),email_confirmed_at from auth.users on conflict(user_id) do update set email=excluded.email,confirmed_at=excluded.confirmed_at;